import{_ as n,C as s,o as c,c as i,aj as d,E as r,j as o,a}from"./framework.js";const T=JSON.parse('{"title":"身份验证（Authentication） | Cms / Development | Documentation","description":"为站点前台请求配置 访问控制规则：按 URL / HTTP 方法匹配请求，再执行 JWT 校验 或 自定义 KScript，未通过时可返回 HTTP 状态码或重定向。规则在站点页面/API 等已绑定路由的请求进入渲染前执行。","frontmatter":{"title":"身份验证（Authentication） | Cms / Development | Documentation","description":"为站点前台请求配置 访问控制规则：按 URL / HTTP 方法匹配请求，再执行 JWT 校验 或 自定义 KScript，未通过时可返回 HTTP 状态码或重定向。规则在站点页面/API 等已绑定路由的请求进入渲染前执行。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/development/authentication.html"}]]},"headers":[],"relativePath":"zh/cms/development/authentication.md","filePath":"cms/development/authentication.md","lastUpdated":1780542614000}'),h={name:"zh/cms/development/authentication.md"};function l(g,t,u,p,b,m){const e=s("DocImage");return c(),i("div",null,[t[0]||(t[0]=d('<h1 id="身份验证-authentication" tabindex="-1">身份验证（Authentication） <a class="header-anchor" href="#身份验证-authentication" aria-label="Permalink to &quot;身份验证（Authentication）&quot;">​</a></h1><blockquote><p>菜单：<strong>开发 → 身份验证</strong><br> 深链：<code>/_Admin/development/authentication?SiteId={站点GUID}</code></p></blockquote><p>为站点前台请求配置 <strong>访问控制规则</strong>：按 URL / HTTP 方法匹配请求，再执行 <strong>JWT 校验</strong> 或 <strong>自定义 KScript</strong>，未通过时可返回 HTTP 状态码或重定向。规则在站点页面/API 等已绑定路由的请求进入渲染前执行。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><p>菜单权限：<code>authentication</code>（查看）。<strong>创建</strong>、编辑规则需 <code>authentication·edit</code>；列表多选 <strong>删除</strong> 需 <code>authentication·delete</code>。</p></div><div class="info custom-block"><p class="custom-block-title">与站点账号登录的区别</p><p>本页控制的是 <strong>访客请求是否允许继续渲染</strong>（网关式规则），不是 Kooboo 后台账号登录，也不是 <a href="/kb-docs/zh/api/getting-started/auth.html">k.account</a> 的站点账号登录流程。JWT 校验使用 <a href="/kb-docs/zh/api/security/">k.security.jwt</a> 解码请求中的令牌。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>开发 → 身份验证</strong>。</li><li>左侧 <strong>开发 → 身份验证</strong>。</li></ol>',7)),r(e,{src:"/cms/development/authentication-overview.png",alt:"身份验证列表总览",width:"1120"}),t[1]||(t[1]=d('<h2 id="规则列表" tabindex="-1">规则列表 <a class="header-anchor" href="#规则列表" aria-label="Permalink to &quot;规则列表&quot;">​</a></h2><h3 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to &quot;工具栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按钮</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><strong>创建</strong></td><td><code>authentication·edit</code></td><td>打开 <a href="#新建与编辑规则弹窗">新建/编辑规则弹窗</a></td></tr></tbody></table>',3)),r(e,{src:"/cms/development/authentication-toolbar.png",alt:"身份验证工具栏",width:"1120"}),t[2]||(t[2]=d('<h3 id="列表表格" tabindex="-1">列表表格 <a class="header-anchor" href="#列表表格" aria-label="Permalink to &quot;列表表格&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>规则唯一标识（新建后不可在此列表改名称，仅编辑弹窗内配置）</td></tr><tr><td><strong>匹配器</strong></td><td><code>None</code> / <code>Any</code> / <code>Condition</code>；为 <code>Condition</code> 时显示条件摘要（如 <code>url = &#39;/api&#39;</code>）</td></tr><tr><td><strong>操作</strong></td><td><code>None</code> / <code>JwtAuth</code> / <code>CustomCode</code></td></tr><tr><td><strong>失败操作</strong></td><td><code>None</code> / <code>ResultCode</code> / <code>Redirect</code>；操作为 <code>CustomCode</code> 时列显示 <code>CustomCode</code></td></tr><tr><td><strong>参数</strong></td><td>失败时相关参数：自定义代码名称、<code>httpCode</code>、重定向 <code>url</code> 等</td></tr><tr><td><strong>最后修改</strong></td><td>保存时间</td></tr><tr><td><strong>操作</strong></td><td><strong>设置</strong> 图标进入 <a href="#新建与编辑规则弹窗">编辑</a></td></tr></tbody></table><p>支持多选 <strong>删除</strong>（<code>authentication·delete</code>）。</p>',3)),r(e,{src:"/cms/development/authentication-list-table.png",alt:"身份验证列表",width:"1120"}),t[3]||(t[3]=o("h2",{id:"新建与编辑规则弹窗",tabindex:"-1"},[a("新建与编辑规则弹窗 "),o("a",{class:"header-anchor",href:"#新建与编辑规则弹窗","aria-label":'Permalink to "新建与编辑规则弹窗"'},"​")],-1)),t[4]||(t[4]=o("p",null,[a("点击 "),o("strong",null,"创建"),a(" 或行末 "),o("strong",null,"设置"),a(" 打开。新建需填写 "),o("strong",null,"名称"),a("（1～50 字符，字母或数字开头、唯一）；编辑已有规则时名称不可改。")],-1)),r(e,{src:"/cms/development/authentication-edit-dialog.png",alt:"身份验证规则编辑弹窗",width:"1120"}),t[5]||(t[5]=d('<h3 id="匹配器-matcher" tabindex="-1">匹配器（Matcher） <a class="header-anchor" href="#匹配器-matcher" aria-label="Permalink to &quot;匹配器（Matcher）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>不参与匹配（通常用于占位，实际不会命中请求）</td></tr><tr><td><strong>Any</strong></td><td>匹配所有进入规则链的请求</td></tr><tr><td><strong>Condition</strong></td><td>按下方条件匹配；多条条件为 <strong>且（&amp;&amp;）</strong> 关系，须全部满足</td></tr></tbody></table><p><strong>Condition</strong> 时每行包含：</p><table tabindex="0"><thead><tr><th>字段</th><th>可选值</th><th>说明</th></tr></thead><tbody><tr><td>左侧</td><td><code>url</code>、<code>method</code></td><td>分别为请求相对路径、HTTP 方法</td></tr><tr><td>运算符</td><td><code>=</code>、<code>!=</code>、<code>contains</code>、<code>notcontains</code>、<code>startwith</code>、<code>notstartwith</code></td><td>比较时不区分大小写</td></tr><tr><td>右侧</td><td>文本</td><td>与左侧字段比较的值</td></tr></tbody></table><p>可 <strong>添加</strong> / <strong>删除</strong> 条件行；至少保留一条有效条件，否则无法保存。</p>',5)),r(e,{src:"/cms/development/authentication-condition.png",alt:"Condition 匹配器与条件行",width:"1120"}),t[6]||(t[6]=d('<h3 id="操作-action" tabindex="-1">操作（Action） <a class="header-anchor" href="#操作-action" aria-label="Permalink to &quot;操作（Action）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>匹配后放行，不做校验</td></tr><tr><td><strong>JwtAuth</strong></td><td>使用 JWT 解码校验；失败时执行下方 <strong>失败操作</strong></td></tr><tr><td><strong>CustomCode</strong></td><td>执行内联 <strong>TypeScript/KScript</strong>（Monaco 编辑器）；失败时由脚本设置响应状态</td></tr></tbody></table><p>选择 <strong>CustomCode</strong> 时显示代码编辑器，默认含示例：检查 <code>Authorization</code> 头并调用 <code>k.response.unauthorized()</code>。保存的是内联 <code>customCode</code> 正文（亦可与站点 <strong>代码</strong> 资源关联，列表加载时可能回填 <code>customCodeName</code> 对应正文）。</p><p>选择 <strong>JwtAuth</strong> 时显示 <strong>失败操作</strong> 区块（见下）。</p><h3 id="失败操作-failedaction" tabindex="-1">失败操作（FailedAction） <a class="header-anchor" href="#失败操作-failedaction" aria-label="Permalink to &quot;失败操作（FailedAction）&quot;">​</a></h3><p>仅在 <strong>操作</strong> 为 <strong>JwtAuth</strong> 时出现（<code>CustomCode</code> 由脚本自行处理响应）。</p><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>JWT 校验失败时，将解码结果中的 <code>value</code> 写入响应正文</td></tr><tr><td><strong>ResultCode</strong></td><td>返回指定 <strong>HTTP 状态码</strong>（如 <code>401</code>）</td></tr><tr><td><strong>Redirect</strong></td><td><strong>302</strong> 重定向到填写的 <strong>URL</strong>；自动附带 <code>returnurl</code> 查询参数（当前请求路径）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>附加字段</th><th>何时显示</th><th>说明</th></tr></thead><tbody><tr><td><strong>HTTP 状态码</strong></td><td><code>ResultCode</code></td><td>必填，合法 HTTP 状态码</td></tr><tr><td><strong>URL</strong></td><td><code>Redirect</code></td><td>必填，重定向目标（输入时自动去除空格）</td></tr></tbody></table><h2 id="规则如何生效" tabindex="-1">规则如何生效 <a class="header-anchor" href="#规则如何生效" aria-label="Permalink to &quot;规则如何生效&quot;">​</a></h2><ul><li>仅对 <strong>已绑定站点路由</strong> 的请求生效（有 <code>Route.objectId</code> 的页面、API 等）；纯静态或未匹配路由的请求不经过此列表。</li><li>系统按站点内规则 <strong>列表顺序</strong> 依次尝试匹配；<strong>第一条</strong> 匹配成功的规则被执行，后续规则不再检查。多条规则并存时请把更具体的 <code>Condition</code> 排在前面，或避免重叠的 <code>Any</code>。</li><li><code>JwtAuth</code>：解码成功且结果 <code>code !== 1</code> 时放行，并将 <code>value</code> 放入请求上下文 <code>jwt_payload</code>；<code>code === 1</code> 视为失败，按 <strong>失败操作</strong> 处理。</li><li><code>CustomCode</code>：执行脚本后若响应状态码 <strong>小于 300</strong> 则放行，否则请求终止（中间件可能返回 <strong>403</strong>）。</li><li>校验未通过且未写入完整响应时，可能返回 <strong>403</strong>。</li></ul><p>自定义代码中常用 API：<a href="/kb-docs/zh/api/request/">k.request</a>、<a href="/kb-docs/zh/api/response/">k.response</a>（如 <code>unauthorized()</code>）、<a href="/kb-docs/zh/api/security/">k.security.jwt</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">开发概述</a></td><td>开发分组索引</td></tr><tr><td><a href="./code.html">代码</a></td><td>CodeBlock，可与 CustomCode 配合</td></tr><tr><td><a href="/kb-docs/zh/api/security/">k.security.jwt</a></td><td>JWT 编解码</td></tr><tr><td><a href="/kb-docs/zh/api/response/">k.response</a></td><td><code>unauthorized()</code>、重定向等</td></tr><tr><td><a href="/kb-docs/zh/api/getting-started/auth.html">认证与授权（API）</a></td><td><code>k.account</code> 会员登录（非本页规则）</td></tr></tbody></table>',13))])}const C=n(h,[["render",l]]);export{T as __pageData,C as default};
